  async function assignCustomRole(row:AdminRecord,roleId:string){const id=String(row.id??row._id??'');if(!id||!roleId)return;setAssigningAdmin(id);setDetail('');try{await assignAdministratorRole(id,roleId);setDetail(`Custom administrator role assigned to ${String(row.fullName??row.email??'account')}.`);reload();}catch(cause){setDetail(cause instanceof Error?cause.message:'Administrator role assignment failed.');setState('error');}finally{setAssigningAdmin('');}}
  async function updateAccountRole(row:AdminRecord,role:string){const id=String(row.id??row._id??'');if(!id||!role||role===String(row.accountType??row.role??''))return;setChangingUserRole(id);setDetail('');try{await changeUserRole(id,role);setDetail(`Account role updated for ${String(row.fullName??row.email??'account')}.`);reload();}catch(cause){setDetail(cause instanceof Error?cause.message:'Account role could not be updated.');setState('error');}finally{setChangingUserRole('');}}
