  async function inspectLedger(row:AdminRecord){const id=String(row.id??row._id??'');if(!id)return;const request=++ledgerRequest.current;setSelectedLedger(null);setLedgerError('');setLedgerLoading(true);try{const result=await loadAdminLedgerDetails(row.recordType==='payment'?'payment':'order',id);if(request===ledgerRequest.current)setSelectedLedger(result);}catch(cause){if(request===ledgerRequest.current)setLedgerError(cause instanceof Error?cause.message:'Financial record details are unavailable.');}finally{if(request===ledgerRequest.current)setLedgerLoading(false);}}
  async function inspectSupport(row:AdminRecord){const id=String(row.id??row._id??'');if(!id)return;const request=++ledgerRequest.current;setSelectedLedger(null);setLedgerError('');setLedgerLoading(true);try{const result=await loadAdminSupportDetails(id);if(request===ledgerRequest.current)setSelectedLedger({...result,type:'support'});}catch(cause){if(request===ledgerRequest.current)setLedgerError(cause instanceof Error?cause.message:'Support details are unavailable.');}finally{if(request===ledgerRequest.current)setLedgerLoading(false);}}
