  async function openUserDetails(row:AdminRecord){const id=String(row.id??row._id??'');if(!id)return;const request=++detailsRequest.current;setSelectedUser(null);setDetailsError('');setDetailsLoading(true);try{const result=await loadAdminUserDetails(id);if(request===detailsRequest.current){setSelectedUser(result);setUserDraft({fullName:String(result.user.fullName??''),phone:String(result.user.phone??''),county:String(result.user.county??'')});}}catch(cause){if(request===detailsRequest.current)setDetailsError(cause instanceof Error?cause.message:'User details are unavailable.');}finally{if(request===detailsRequest.current)setDetailsLoading(false);}}
  async function saveUserDetails(event:FormEvent){event.preventDefault();const id=String(selectedUser?.user.id??'');if(!id||!userDraft.fullName.trim())return;setUserSaving(true);setDetailsError('');try{const result=await updateAdminUserDetails(id,{fullName:userDraft.fullName.trim(),phone:userDraft.phone.trim()||null,county:userDraft.county.trim()||null});setSelectedUser(current=>current?{...current,user:result.user}:current);setOperationNotice('Permitted account information was saved to the shared database.');reload();}catch(cause){setDetailsError(cause instanceof Error?cause.message:'Account information could not be updated.');}finally{setUserSaving(false);}}
  async function addCategory(event:FormEvent){event.preventDefault();if(!name.trim())return;try{await createCategory(name.trim());setName('');reload();}catch(cause){setDetail(cause instanceof Error?cause.message:'Category could not be created.');setState('error');}}
  async function renameCategory(row:AdminRecord){const id=String(row.id??row._id??'');if(!id)return;const nextName=window.prompt('Category name',String(row.name??''));if(nextName===null)return;if(nextName.trim().length<2||nextName.trim().length>80){setOperationNotice('Enter a category name between 2 and 80 characters.');return;}try{const result=await updateCategory(id,{name:nextName.trim()});setOperationNotice(`Category saved with slug ${String(result.slug??'unavailable')}.`);reload();}catch(cause){setDetail(cause instanceof Error?cause.message:'Category could not be updated.');setState('error');}}
