  async function runMarketSourceSync(row:AdminRecord){const id=String(row.id??row._id??'');if(!id)return;setSyncingSource(id);setSyncStatus('');try{const result=await syncMarketSource(id);setSyncStatus(`KAMIS sync complete: ${result.recordsAccepted??0} new observations, ${result.recordsUnavailable??0} unavailable quotes, ${result.recordsRejected??0} rejected quotes.`);reload();}catch(cause){setSyncStatus(cause instanceof Error?`KAMIS sync failed: ${cause.message}`:'KAMIS sync failed.');}finally{setSyncingSource('');}}
